-- ============================================
-- SEED DATA: Dữ liệu hành chính toàn quốc & Lịch sử sáp nhập
-- Sinh tự động từ Database (Giữ nguyên ID gốc)
-- ============================================
SET client_encoding = 'UTF8';
SET session_replication_role = 'replica'; -- Tắt trigger khóa ngoại tạm thời nếu có

-- Xóa dữ liệu cũ
TRUNCATE TABLE administrative_change_mappings RESTART IDENTITY CASCADE;
TRUNCATE TABLE administrative_changes RESTART IDENTITY CASCADE;
TRUNCATE TABLE administrative_units RESTART IDENTITY CASCADE;

